 async function refreshAvailability(){try{const r=await fetch('/api/availability',{cache:'no-store'});if(!r.ok)throw new Error('Current availability could not load. Showing the saved research status.');const d=await r.json() as {records:Record<string,Availability>;canEdit:boolean};setAvailability(d.records??{});setCanEditAvailability(!!d.canEdit);setAvailabilityError('')}catch(e){setAvailabilityError(e instanceof Error?e.message:'Availability could not load.')}}
 async function saveAvailability(spotId:string,next:Availability){const {revision,...status}=next;const r=await fetch('/api/availability',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({spotId,expectedRevision:revision??0,availability:status})});const d=await r.json() as {record:Availability;error?:string};if(!r.ok)throw new Error(d.error??'Could not save availability.');setAvailability(a=>({...a,[spotId]:d.record}));return d.record as Availability;}
 const [prefs,setPrefs]=useState<Preferences>(DEFAULT_PREFS),[journal,setJournal]=useState<Journal>({}),[hydrated,setHydrated]=useState(false),[sync,setSync]=useState('Connecting'),[syncError,setSyncError]=useState(''),[selectedId,setSelectedId]=useState<string|null>(null),[sidebar,setSidebar]=useState(true),[filterOpen,setFilterOpen]=useState(false),[researchOpen,setResearchOpen]=useState(false),[action,setAction]=useState({type:'',nonce:0}),[tab,setTab]=useState('overview'),[detailHidden,setDetailHidden]=useState(false);
 const pendingPrefs=useRef<Partial<Preferences>>({}),saving=useRef(false),timer=useRef<ReturnType<typeof setTimeout>|null>(null),prefsRef=useRef(prefs),mounted=useRef(true),authenticated=useRef(false);
 const [favoriteBusy,setFavoriteBusy]=useState<string[]>([]),[favoriteNotice,setFavoriteNotice]=useState(''),[favoriteError,setFavoriteError]=useState(false),[personalRefreshing,setPersonalRefreshing]=useState(true);
