  if(sharedView.current.filters&&(patch.filters||patch.sort)){patch={filters:prefsRef.current.filters,sort:prefsRef.current.sort,...patch};sharedView.current={spot:sharedView.current.spot};setSharedFilters(false);const url=new URL(window.location.href);const hash=new URLSearchParams(url.hash.slice(1));hash.delete('filters');hash.delete('sort');url.hash=hash.toString();window.history.replaceState(null,'',url)}
